{
  "args": {
    "path": "mdkit",
    "content": "def toc(file, depth=None):
    """Print the table of contents of a page as a nested Markdown list."""
    from mdkit.core import Document
    doc = Document(file)
    toc_list = []
    for heading in doc.headings:
        if heading.level > 1 and (depth is None or heading.level <= depth):
            toc_list.append(f"- [{heading.text}]({heading.anchor})")
    return '\n'.join(toc_list)

def toc_write(file, depth=None):
    """Keep the table of contents in the page itself."""
    from mdkit.core import Document
    doc = Document(file)
    toc_list = []
    for heading in doc.headings:
        if heading.level > 1 and (depth is None or heading.level <= depth):
            toc_list.append(f"- [{heading.text}]({heading.anchor})")
    toc_text = '\n'.join(toc_list)
    start_line = doc.find_line("<!-- toc -->")
    end_line = doc.find_line("<!-- /toc -->")
    if start_line is not None and end_line is not None:
        doc.replace_lines(start_line, end_line, toc_text)
    else:
        print("Error: Missing <!-- toc --> or <!-- /toc --> lines.")
        exit(2)
    doc.save()
"
